def _json_depth(text: str) -> int:
    """The deepest bracket nesting in `text`, ignoring brackets in strings.

    A single pass, no recursion, so the answer does not depend on the
    interpreter's stack. Brackets inside string literals are not structure --
    ``{"a": "[[[["}`` is depth one -- so the scanner tracks whether it is
    inside a string and honours backslash escapes. Anything malformed is left
    for ``json.loads`` to reject; this only counts.
    """
    depth = maximum = 0
    in_string = escaped = False
    for character in text:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character in "[{":
            depth += 1
            if depth > maximum:
                maximum = depth
        elif character in "]}":
            depth -= 1
    return maximum

def _execute_argv(argv: Sequence[str], cwd: Path, timeout: float,
                  max_output: int) -> CommandResult:
    """Execute a fixed argv while monitoring output files and wall-clock time.

    Temporary files keep child output out of process memory.  The child is
    killed as soon as either output boundary is observed.
    """
    if not isinstance(argv, (list, tuple)) or not argv or not all(
            isinstance(item, str) for item in argv):
        raise GitIntelligenceError("Git argv must be a non-empty text sequence")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise GitIntelligenceError("Git timeout must be positive")
    env = os.environ.copy()
    env.update({
        "GIT_TERMINAL_PROMPT": "0", "GIT_OPTIONAL_LOCKS": "0",
        "GIT_PAGER": "cat", "PAGER": "cat", "GIT_CONFIG_NOSYSTEM": "1",
        "LC_ALL": "C", "LANG": "C",
    })
    env.pop("GIT_EXTERNAL_DIFF", None)
    with tempfile.TemporaryFile() as stdout_file, tempfile.TemporaryFile() as stderr_file:
        try:
            process = subprocess.Popen(
                list(argv), cwd=str(cwd), stdin=subprocess.DEVNULL,
                stdout=stdout_file, stderr=stderr_file, shell=False,
                close_fds=True, env=env,
            )
        except OSError as exc:
            raise GitIntelligenceError("Git could not be started: " + str(exc)[:240]) from exc
        deadline = time.monotonic() + float(timeout)
        reason = ""
        while process.poll() is None:
            if time.monotonic() >= deadline:
                reason = "timeout"
                break
            try:
                if os.fstat(stdout_file.fileno()).st_size > max_output or \
                        os.fstat(stderr_file.fileno()).st_size > MAX_GIT_STDERR:
                    reason = "output"
                    break
            except OSError:
                reason = "output"
                break
            time.sleep(0.01)
        if reason:
            process.kill()
        try:
            process.wait(timeout=2)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()
        stdout_size = os.fstat(stdout_file.fileno()).st_size
        stderr_size = os.fstat(stderr_file.fileno()).st_size
        if reason == "timeout":
            raise GitTimeoutError("Git command exceeded its wall-clock timeout")
        if reason == "output" or stdout_size > max_output or stderr_size > MAX_GIT_STDERR:
            raise GitOutputLimitError("Git command exceeded its output boundary")
        stdout_file.seek(0)
        stderr_file.seek(0)
        return CommandResult(process.returncode, stdout_file.read(max_output + 1),
                             stderr_file.read(MAX_GIT_STDERR + 1))

def _terminal_json(value: Any, depth: int = 0) -> Any:
    """Return JSON-shaped advisory data with terminal-safe keys and strings."""
    if depth > 128:
        raise SupplyChainTrustError("advisory nesting exceeds boundary")
    if isinstance(value, str):
        return _terminal_text(value, max(1, len(value) * 6))
    if isinstance(value, (list, tuple)):
        return [_terminal_json(item, depth + 1) for item in value]
    if type(value) is dict:
        result: dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise SupplyChainTrustError("advisory object key is not text")
            safe_key = _terminal_text(key, max(1, len(key) * 6))
            if safe_key in result:
                raise SupplyChainTrustError("advisory keys collide after control escaping")
            result[safe_key] = _terminal_json(item, depth + 1)
        return result
    return value

