class DetectionPattern:
    """A pattern Owen learned or mined from its own results."""
    pattern_id: str
    cwe: str
    language: str
    regex: str
    description: str
    source: str  # "builtin", "mined", "generated"
    hit_count: int = 0
    false_positive_count: int = 0
    generation_added: int = 0

    @property
    def precision(self) -> float:
        total = self.hit_count + self.false_positive_count
        if total == 0:
            return 1.0
        return self.hit_count / total

    @property
    def is_reliable(self) -> bool:
        return self.hit_count >= 3 and self.precision >= 0.7

def _robots_specificity(pattern: str) -> int:
    """Count path octets, excluding wildcard syntax, for longest-match ties."""
    count = index = 0
    while index < len(pattern):
        if pattern[index] == "*":
            index += 1
        elif pattern[index] == "%" and index + 2 < len(pattern) and re.fullmatch(
                r"[0-9A-F]{2}", pattern[index + 1:index + 3]):
            count += 1
            index += 3
        else:
            count += len(pattern[index].encode("utf-8"))
            index += 1
    return count

