def _strip_comments(text: str, language: str) -> str:
    """Replace comments with spaces while preserving strings and line offsets."""
    out = list(text)
    size = len(text)
    i = 0
    quote = ""
    escaped = False
    block_depth = 0
    while i < size:
        char = text[i]
        nxt = text[i + 1] if i + 1 < size else ""
        if block_depth:
            if language == "rust" and char == "/" and nxt == "*":
                out[i] = out[i + 1] = " "
                block_depth += 1
                i += 2
                continue
            if char == "*" and nxt == "/":
                out[i] = out[i + 1] = " "
                block_depth -= 1
                i += 2
                continue
            if char != "\n":
                out[i] = " "
            i += 1
            continue
        if quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            i += 1
            continue
        if char in {"'", '"', "`"}:
            quote = char
            i += 1
            continue
        if char == "/" and nxt == "*":
            out[i] = out[i + 1] = " "
            block_depth = 1
            i += 2
            continue
        if char == "/" and nxt == "/":
            while i < size and text[i] != "\n":
                out[i] = " "
                i += 1
            continue
        if language == "php" and char == "#" and nxt != "[":
            while i < size and text[i] != "\n":
                out[i] = " "
                i += 1
            continue
        i += 1
    return "".join(out)

