def _note_allocation(kinds, line):
    """Record how `line` allocated something, if it did."""
    declared = BUFFER_DECL.match(line)
    if declared:
        kinds[declared.group(2)] = "stack"
        return
    match = C_ALLOC_KIND.match(line)
