def _counted(source: str, dim: int) -> tuple[dict[int, int], int]:
    """{bucket: count} and the token total, touching only occupied buckets."""
    tokens = tokenize(source[:MAX_SOURCE_BYTES])
    counts: dict[int, int] = {}
    last = len(tokens) - 1
    for position, token in enumerate(tokens):
        key = _hashed(token) % dim
        counts[key] = counts.get(key, 0) + 1
        if position < last:
            key = _hashed("\x00".join(tokens[position:position + 2])) % dim
            counts[key] = counts.get(key, 0) + 1
        if position + 1 < last:
            key = _hashed("\x01".join(tokens[position:position + 3])) % dim
            counts[key] = counts.get(key, 0) + 1
    return counts, max(1, len(tokens))

def _read_baseline(path: Path) -> bytes:
    """Reject oversized baselines by metadata, then retain a race-safe read cap."""
    try:
        info = path.stat()
        if not stat.S_ISREG(info.st_mode) or info.st_size > MAX_FILE_BYTES:
            raise RepairDirectorError("baseline file exceeds the size boundary")
        with path.open("rb") as stream:
            raw = stream.read(MAX_FILE_BYTES + 1)
    except RepairDirectorError:
        raise
    except OSError as exc:
        raise RepairDirectorError("baseline file is unavailable") from exc
    if len(raw) > MAX_FILE_BYTES:
        raise RepairDirectorError("baseline file exceeds the size boundary")
    return raw

