def _expand(text, macros, rounds=3):
    """Substitute object-like macros, bounded so a cycle cannot hang a scan."""
    for _ in range(rounds):
        grown = re.sub(r"\b(\w+)\b",
                       lambda m: macros.get(m.group(1), m.group(0)), text)
        if grown == text:
            break
        text = grown
    return text

