def _robots_can_fetch(text: str, url: str, agent: str) -> bool:
    """Bounded longest-match robots evaluator for User-agent/Allow/Disallow."""
    if len(text.encode("utf-8", "replace")) > MAX_ROBOTS_BYTES:
        return False
    groups: list[tuple[list[str], list[tuple[bool, str]]]] = []
    agents: list[str] = []
    rules: list[tuple[bool, str]] = []
    saw_rule = False
    for raw in text.splitlines()[:20_000]:
        line = raw.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        name, value = (item.strip() for item in line.split(":", 1))
        lower = name.casefold()
        if lower == "user-agent":
            if saw_rule and agents:
                groups.append((agents, rules)); agents, rules, saw_rule = [], [], False
            product = value.casefold()
            if product == "*" or re.fullmatch(r"[a-z_-]+", product):
                agents.append(product)
        elif lower in {"allow", "disallow"} and agents:
            saw_rule = True
            if value or lower == "allow":
                rules.append((lower == "allow", value))
    if agents:
        groups.append((agents, rules))
    token = agent.casefold()
    if not re.fullmatch(r"[a-z_-]+", token):
        return False
    exact = [rules for names, rules in groups if token in names]
    selected = exact if exact else [rules for names, rules in groups if "*" in names]
    combined = [rule for group in selected for rule in group]
    parsed_url = urlsplit(url)
    path = _robots_octet_spelling((parsed_url.path or "/") + (
        "?" + parsed_url.query if parsed_url.query else "")
    )
    if path == "/robots.txt":
        return True
    matches: list[tuple[int, bool]] = []
    for allow, pattern in combined:
        if not pattern:
            continue
        anchored = pattern.endswith("$")
        value = _robots_octet_spelling(pattern[:-1] if anchored else pattern)
        expression = "^" + re.escape(value).replace(r"\*", ".*") + ("$" if anchored else "")
        try:
            if re.search(expression, path):
                matches.append((_robots_specificity(value), allow))
        except re.error:
            continue
    if not matches:
        return True
    longest = max(length for length, _allow in matches)
    # Equivalent Allow and Disallow matches resolve to Allow.
    return any(allow for length, allow in matches if length == longest)

def apply_constraint(buf, constraint, mode):
    """mode 'falsify' drives past the guard; mode 'satisfy' takes it."""
    form = constraint["form"]
    falsify = mode == "falsify"

    if form == "eq_byte":
        index = constraint["index"]
        while index >= len(buf):
            buf.extend(b"\x00")
        target = _byte_of(constraint["value"])
        # guard 'data[i] == c': satisfy => byte equals c, falsify => differs
        buf[index] = target if mode == "satisfy" else ((target ^ 1) & 0xFF)
    elif form == "neq_byte":
        index = constraint["index"]
        while index >= len(buf):
            buf.extend(b"\x00")
        target = _byte_of(constraint["value"])
        # guard 'data[i] != c': satisfy => differs, falsify => equals c
        buf[index] = ((target ^ 1) & 0xFF) if mode == "satisfy" else target
    elif form == "startswith":
        prefix = constraint["prefix"].encode("latin-1", errors="replace")
        negated = constraint.get("negated", False)
        present_needed = negated ^ (mode == "satisfy")
        if present_needed and prefix:
            buf[:len(prefix)] = prefix
        elif prefix and buf:
            buf[0] = (_byte_of(prefix[0]) ^ 1) & 0xFF
    elif form == "len_lt":
        if mode == "falsify":
            while len(buf) < constraint["n"]:
                buf.extend(b"\x00")
        else:
            del buf[max(1, constraint["n"] - 1):]
    elif form == "len_ge":
        if mode == "falsify":
            del buf[max(1, constraint["n"] - 1):]
        else:
            while len(buf) < constraint["n"]:
                buf.extend(b"\x00")

#!/usr/bin/env python3
"""
nativepool.py -- run a per-file scan across all your cores.

Every native engine here processes one file independently, so scanning a tree is
embarrassingly parallel. This is the shared helper: pmap(func, items, jobs) fans
the work out over a process pool (stdlib multiprocessing, zero dependencies) and
falls back to a plain serial map for jobs<=1 or a single item. Nothing else about
the engines changes -- they just finish sooner on a big codebase.
"""
from __future__ import annotations

import multiprocessing
import os


def default_jobs() -> int:
    return os.cpu_count() or 1


def resolve(jobs) -> int:
    """Turn a --jobs value into a worker count: 0 (or None) means 'all cores'."""
    if not jobs:
        return default_jobs()
    return max(1, int(jobs))


def pmap(func, items, jobs) -> list:
    """Map func over items, in parallel when it pays off. func must be a top-level
    (picklable) function. Order of results matches order of items."""
    items = list(items)
    workers = resolve(jobs)
    if workers <= 1 or len(items) <= 1:
        return [func(item) for item in items]
    with multiprocessing.Pool(processes=workers) as pool:
        return pool.map(func, items)

