class RepoFetcher:
    """Clones or downloads repository contents to a local directory."""

    def __init__(self, work_dir: str | None = None):
        self._work_dir = work_dir or tempfile.mkdtemp(prefix="owen_ingest_")
        self._has_git = shutil.which("git") is not None

    @property
    def work_dir(self) -> str:
        return self._work_dir

    def fetch(self, entry: RepoEntry) -> str:
        """Fetch repository contents. Returns local path."""
        dest = os.path.join(self._work_dir, entry.repo_id)
        if os.path.exists(dest):
            return dest

        if self._has_git and entry.fetch_method == FetchMethod.GIT_CLONE:
            return self._git_clone(entry, dest)
        return self._api_download(entry, dest)

    def _git_clone(self, entry: RepoEntry, dest: str) -> str:
        clone_url = "https://github.com/%s/%s.git" % (entry.owner, entry.name)
        try:
            subprocess.run(
                ["git", "clone", "--depth", "1", "--single-branch",
                 "--no-tags", clone_url, dest],
                capture_output=True, text=True, timeout=120,
                env={**os.environ, "GIT_TERMINAL_PROMPT": "0"})
        except subprocess.TimeoutExpired:
            raise RuntimeError("git clone timed out for %s" % entry.full_name)

        if not os.path.isdir(dest):
            raise RuntimeError("git clone failed for %s" % entry.full_name)

        git_dir = os.path.join(dest, ".git")
        if os.path.isdir(git_dir):
            shutil.rmtree(git_dir, ignore_errors=True)

        return dest

    def _api_download(self, entry: RepoEntry, dest: str) -> str:
        """Download via GitHub API tarball."""
        import urllib.request
        url = "https://api.github.com/repos/%s/%s/tarball" % (
            entry.owner, entry.name)
        headers = {"User-Agent": "Owen-Attestor/4.2"}
        token = os.environ.get("GITHUB_TOKEN", "")
        if token:
            headers["Authorization"] = "token %s" % token

        tarball = dest + ".tar.gz"
        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=60) as resp:
                with open(tarball, "wb") as f:
                    while True:
                        chunk = resp.read(65536)
                        if not chunk:
                            break
                        f.write(chunk)
        except Exception as e:
            raise RuntimeError("API download failed for %s: %s" %
                               (entry.full_name, e))

        os.makedirs(dest, exist_ok=True)
        try:
            import tarfile
            with tarfile.open(tarball, "r:gz") as tf:
                tf.extractall(dest, filter="data")
        except Exception as e:
            raise RuntimeError("tarball extraction failed: %s" % e)
        finally:
            try:
                os.unlink(tarball)
            except OSError:
                pass

        return dest

    def cleanup(self, entry: RepoEntry) -> None:
        dest = os.path.join(self._work_dir, entry.repo_id)
        if os.path.isdir(dest):
            shutil.rmtree(dest, ignore_errors=True)

    def cleanup_all(self) -> None:
        if os.path.isdir(self._work_dir):
            shutil.rmtree(self._work_dir, ignore_errors=True)

def _git_show(ref: str, path: str) -> str:
    """The contents of `path` at git `ref` (e.g. HEAD), or '' if unavailable."""
    try:
        proc = subprocess.run(["git", "show", "%s:%s" % (ref, path)],
                              capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return ""
    return proc.stdout if proc.returncode == 0 else ""

def stride_for(category: str, rule: str = "") -> list[str]:
    """Return applicable STRIDE threat classes, ordered and deduplicated."""
    text = " ".join((category, rule)).lower()
    values: list[str] = []
    if any(word in text for word in ("auth", "identity", "credential", "token")):
        values += ["Spoofing", "Elevation of Privilege"]
    if any(word in text for word in ("access", "authorization", "privilege", "admin")):
        values += ["Elevation of Privilege"]
    if any(word in text for word in ("injection", "integrity", "supply", "dependency",
                                      "workflow", "ci", "iac", "cloud")):
        values += ["Tampering"]
    if any(word in text for word in ("secret", "data", "exposure", "leak", "cors", "cookie")):
        values += ["Information Disclosure"]
    if any(word in text for word in ("logging", "audit")):
        values += ["Repudiation"]
    if any(word in text for word in ("availability", "resource", "dos", "limit")):
        values += ["Denial of Service"]
    return list(dict.fromkeys(values or ["Tampering"]))

class GenerationResult:
    """Typed result for one provider attempt.

    ``content`` exists only for ``SUCCESS``.  Failure and abstention details
    live in ``error`` and can therefore never masquerade as model output.
    Prompt text is intentionally not retained; evidence stores its digest.
    """

    provider: str
    model: str
    status: GenerationStatus
    content: str | None
    prompt_sha256: str
    response_sha256: str | None
    error: str | None = None

    def __post_init__(self) -> None:
        try:
            status = GenerationStatus(self.status)
        except ValueError as exc:
            raise ValueError("unknown generation status") from exc
        object.__setattr__(self, "status", status)
        if not _is_sha256(self.prompt_sha256):
            raise ValueError("prompt_sha256 must be a lowercase SHA-256 digest")
        if self.status is GenerationStatus.SUCCESS:
            if not self.content:
                raise ValueError("successful generation must contain model output")
            expected = _sha256_text(self.content)
            if self.response_sha256 != expected:
                raise ValueError("response_sha256 does not match model output")
            if self.error is not None:
                raise ValueError("successful generation cannot contain an error")
        else:
            if self.content is not None or self.response_sha256 is not None:
                raise ValueError("failed/abstained generation cannot contain model output")
        if self.status is GenerationStatus.FAILED and not self.error:
            raise ValueError("failed generation must contain a safe error summary")

    @property
    def success(self) -> bool:
        return self.status is GenerationStatus.SUCCESS

    @property
    def failed(self) -> bool:
        return self.status is GenerationStatus.FAILED

    @property
    def abstained(self) -> bool:
        return self.status is GenerationStatus.ABSTAINED

    @property
    def evidence(self) -> GenerationEvidence:
        return GenerationEvidence(
            provider=self.provider,
            model=self.model,
            status=self.status,
            prompt_sha256=self.prompt_sha256,
            response_sha256=self.response_sha256,
        )

    def evidence_dict(self) -> dict:
        return self.evidence.as_dict()

    def require_content(self) -> str:
        """Return verified response text or fail instead of inventing content."""
        if not self.success or self.content is None:
            detail = (": " + self.error) if self.error else ""
            raise ProviderError(
                f"{self.provider} generation {self.status.value}{detail}")
        return self.content

    def __bool__(self) -> bool:
        return self.success

    def __str__(self) -> str:
        # This is intentionally empty for non-success states.  Older callers
        # commonly use ``str(value).strip()`` before treating it as a candidate.
        return self.content if self.success and self.content is not None else ""

    def __contains__(self, value: object) -> bool:
        """Small compatibility bridge for legacy ``'failed' in value`` checks."""
        if not isinstance(value, str):
            return False
        if self.success:
            return value in (self.content or "")
        return value in self.status.value or value in (self.error or "")

def _is_link_or_reparse(path: Path) -> bool:
    """Recognize POSIX links and Windows reparse-backed paths before resolve()."""
    try:
        metadata = path.lstat()
    except OSError:
        return False
    attributes = int(getattr(metadata, "st_file_attributes", 0))
    reparse_flag = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    return stat.S_ISLNK(metadata.st_mode) or bool(attributes & reparse_flag)

