def _mask_literals(text: str) -> str:
    """Mask quoted content without changing offsets or newlines."""
    out = list(text)
    quote = ""
    escaped = False
    for i, char in enumerate(text):
        if quote:
            if char != "\n":
                out[i] = " "
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            continue
        if char in {"'", '"', "`"}:
            out[i] = " "
            quote = char
    return "".join(out)

