class ChainBuilder:
    """Builds exploit chains from findings."""

    def __init__(self, max_chain_length: int = 6,
                 max_chains: int = 50):
        self._findings: list[ChainFinding] = []
        self._max_chain_length = max_chain_length
        self._max_chains = max_chains

    def add_finding(self, cwe: int, rule: str, file_path: str,
                    line: int, **kwargs) -> ChainFinding:
        f = ChainFinding(cwe=cwe, rule=rule, file_path=file_path,
                         line=line, **kwargs)
        self._findings.append(f)
        return f

    def add_findings(self, findings: list[dict[str, Any]]) -> int:
        count = 0
        for f in findings:
            cwe = f.get("cwe", 0)
            if isinstance(cwe, str):
                import re
                m = re.search(r"(\d+)", cwe)
                cwe = int(m.group(1)) if m else 0
            if cwe <= 0:
                continue
            self.add_finding(
                cwe=cwe,
                rule=f.get("rule", "unknown"),
                file_path=f.get("file_path", f.get("path", "")),
                line=f.get("line", 0),
                severity=f.get("severity", "HIGH"),
                message=f.get("message", ""),
                snippet=f.get("snippet", ""),
                language=f.get("language", "unknown"),
            )
            count += 1
        return count

    def add_from_detect(self, findings: list) -> int:
        count = 0
        for f in findings:
            cwe_str = getattr(f, "cwe", "") or ""
            import re
            m = re.search(r"(\d+)", str(cwe_str))
            if not m:
                continue
            self.add_finding(
                cwe=int(m.group(1)),
                rule=getattr(f, "rule", "unknown"),
                file_path=getattr(f, "path", ""),
                line=getattr(f, "line", 0),
                severity=getattr(f, "severity", "HIGH"),
                message=getattr(f, "message", ""),
                snippet=getattr(f, "snippet", ""),
            )
            count += 1
        return count

    def build(self) -> list[KillChain]:
        if not self._findings:
            return []

        impact_map: dict[Impact, list[ChainFinding]] = {}
        for f in self._findings:
            for impact in f.impacts:
                impact_map.setdefault(impact, []).append(f)

        chains: list[KillChain] = []
        seen_chain_ids: set[str] = set()

        for finding in self._findings:
            if finding.stage != ChainStage.INITIAL_ACCESS:
                continue

            for impact in finding.impacts:
                initial_step = ChainStep(
                    finding=finding,
                    stage=finding.stage,
                    impact_achieved=impact,
                )
                self._extend_chain(
                    [initial_step], impact, impact_map,
                    chains, seen_chain_ids, {finding.finding_id})

        chains.sort(key=lambda c: (-c.cvss_estimate, -c.length))
        return chains[:self._max_chains]

    def _extend_chain(self, current_steps: list[ChainStep],
                      current_impact: Impact,
                      impact_map: dict[Impact, list[ChainFinding]],
                      chains: list[KillChain],
                      seen: set[str],
                      used_findings: set[str]) -> None:
        if len(current_steps) >= self._max_chain_length:
            chain = KillChain(steps=list(current_steps))
            if chain.chain_id not in seen:
                seen.add(chain.chain_id)
                chains.append(chain)
            return

        if len(chains) >= self._max_chains:
            return

        next_impacts = CHAIN_EDGES.get(current_impact, [])
        extended = False

        for next_impact in next_impacts:
            for candidate in self._findings:
                if candidate.finding_id in used_findings:
                    continue
                if next_impact not in candidate.impacts:
                    continue

                step = ChainStep(
                    finding=candidate,
                    stage=candidate.stage,
                    impact_achieved=next_impact,
                )
                current_steps.append(step)
                used_findings.add(candidate.finding_id)

                self._extend_chain(
                    current_steps, next_impact, impact_map,
                    chains, seen, used_findings)

                current_steps.pop()
                used_findings.discard(candidate.finding_id)
                extended = True

        if not extended and len(current_steps) >= 2:
            chain = KillChain(steps=list(current_steps))
            if chain.chain_id not in seen:
                seen.add(chain.chain_id)
                chains.append(chain)

    @property
    def finding_count(self) -> int:
        return len(self._findings)

    def findings_by_impact(self) -> dict[str, int]:
        counts: dict[str, int] = {}
        for f in self._findings:
            for impact in f.impacts:
                name = impact.name
                counts[name] = counts.get(name, 0) + 1
        return counts

    def findings_by_stage(self) -> dict[str, int]:
        counts: dict[str, int] = {}
        for f in self._findings:
            name = f.stage.value
            counts[name] = counts.get(name, 0) + 1
        return counts

