class GitHubAPI:
    """Minimal GitHub API client. Uses gh CLI or direct HTTP."""

    def __init__(self, token: str | None = None):
        self._token = token or os.environ.get("GITHUB_TOKEN", "")
        self._has_gh = shutil.which("gh") is not None
        self._rate_remaining = 5000
        self._rate_reset = 0.0

    def _headers(self) -> dict[str, str]:
        h = {"Accept": "application/vnd.github.v3+json",
             "User-Agent": "Owen-Attestor/4.2"}
        if self._token:
            h["Authorization"] = "token %s" % self._token
        return h

    def _gh_api(self, endpoint: str) -> dict | list | None:
        """Call GitHub API via gh CLI."""
        if not self._has_gh:
            return None
        try:
            result = subprocess.run(
                ["gh", "api", endpoint, "--paginate"],
                capture_output=True, text=True, timeout=30)
            if result.returncode == 0 and result.stdout.strip():
                return json.loads(result.stdout)
        except (subprocess.TimeoutExpired, json.JSONDecodeError, OSError):
            pass
        return None

    def _http_get(self, url: str) -> dict | list | None:
        """Call GitHub API via urllib (no external deps)."""
        try:
            import urllib.request
            req = urllib.request.Request(url, headers=self._headers())
            with urllib.request.urlopen(req, timeout=15) as resp:
                remaining = resp.headers.get("X-RateLimit-Remaining", "")
                if remaining:
                    self._rate_remaining = int(remaining)
                return json.loads(resp.read().decode())
        except Exception:
            return None

    def get(self, endpoint: str) -> dict | list | None:
        """GET a GitHub API endpoint. Tries gh CLI first, falls back to HTTP."""
        result = self._gh_api(endpoint)
        if result is not None:
            return result
        url = GITHUB_API + endpoint if endpoint.startswith("/") else endpoint
        return self._http_get(url)

    def repo_info(self, owner: str, name: str) -> dict | None:
        data = self.get("/repos/%s/%s" % (owner, name))
        return data if isinstance(data, dict) else None

    def org_repos(self, org: str, max_repos: int = 500) -> list[dict]:
        """List all public repos for an organization."""
        repos = []
        page = 1
        while len(repos) < max_repos:
            data = self.get(
                "/orgs/%s/repos?type=public&per_page=100&page=%d" % (org, page))
            if not data or not isinstance(data, list) or len(data) == 0:
                break
            repos.extend(data)
            if len(data) < 100:
                break
            page += 1
        return repos[:max_repos]

    def user_repos(self, user: str, max_repos: int = 500) -> list[dict]:
        """List all public repos for a user."""
        repos = []
        page = 1
        while len(repos) < max_repos:
            data = self.get(
                "/users/%s/repos?type=public&per_page=100&page=%d" % (user, page))
            if not data or not isinstance(data, list) or len(data) == 0:
                break
            repos.extend(data)
            if len(data) < 100:
                break
            page += 1
        return repos[:max_repos]

    def search_repos(self, query: str, max_results: int = 100) -> list[dict]:
        """Search GitHub repositories."""
        repos = []
        page = 1
        while len(repos) < max_results:
            data = self.get(
                "/search/repositories?q=%s&per_page=100&page=%d" %
                (query.replace(" ", "+"), page))
            if not data or not isinstance(data, dict):
                break
            items = data.get("items", [])
            if not items:
                break
            repos.extend(items)
            if len(items) < 100:
                break
            page += 1
        return repos[:max_results]

    @property
    def rate_remaining(self) -> int:
        return self._rate_remaining

    @property
    def authenticated(self) -> bool:
        return bool(self._token) or self._has_gh

#!/usr/bin/env python3
"""
fixmemory.py -- durable memory for repeated safe repair patterns.

When evolve.py sees the same mechanical fix across harvested code, Attestor can
record it as a known repair pattern with counts and examples. This is not model
training; it is a plain, inspectable JSON memory.
"""
from __future__ import annotations

import argparse
import json
import os
import time

DEFAULT_MEMORY = os.path.join(os.path.dirname(os.path.abspath(__file__)), "attestor_fix_memory.json")


def load(path: str = DEFAULT_MEMORY) -> dict:
    if not os.path.exists(path):
        return {"version": 1, "patterns": {}}
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def save(memory: dict, path: str = DEFAULT_MEMORY) -> str:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(memory, fh, indent=2, sort_keys=True)
        fh.write("\n")
    return path


def learn(memory: dict, rid: str, note: str, count: int, source: dict | None = None) -> dict:
    key = note or rid
    patterns = memory.setdefault("patterns", {})
    rec = patterns.setdefault(key, {
        "rule": rid,
        "note": note,
        "count": 0,
        "sources": [],
        "first_seen": time.strftime("%Y-%m-%d"),
        "last_seen": "",
        "promoted": False,
    })
    rec["count"] += int(count)
    rec["last_seen"] = time.strftime("%Y-%m-%d")
    if source:
        example = {
            "repo": source.get("repo") or "unknown",
            "path": source.get("path") or "unknown",
            "url": source.get("url") or "",
        }
        if example not in rec["sources"]:
            rec["sources"].append(example)
        rec["sources"] = rec["sources"][-10:]
    if rec["count"] >= 3:
        rec["promoted"] = True
    return rec


def learn_from_evolve_run(run: dict, path: str = DEFAULT_MEMORY) -> dict:
    memory = load(path)
    for result in run.get("results", []):
        source = result.get("source", {})
        for rid, count, note in result.get("applied", []):
            learn(memory, rid, note, count, source)
    save(memory, path)
    return memory


def render(memory: dict) -> str:
    patterns = memory.get("patterns", {})
    out = ["Fix Memory", "=" * 10]
    if not patterns:
        out.append("No repair patterns recorded yet.")
        return "\n".join(out)
    for key, rec in sorted(patterns.items(), key=lambda item: (-item[1].get("count", 0), item[0])):
        badge = "known repair" if rec.get("promoted") else "observed"
        out.append("  %s x%d [%s] %s" % (
            rec.get("rule") or "unknown", rec.get("count", 0), badge, key))
    return "\n".join(out)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--memory", default=DEFAULT_MEMORY)
    args = ap.parse_args(argv)
    print(render(load(args.memory)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

