        defs = {node.name: node for node in ast.walk(tree) if isinstance(node, _DEF)}
        calls = {_call_name(node.func).rsplit(".", 1)[-1]
                 for node in ast.walk(tree) if isinstance(node, ast.Call)}
        for name, node in sorted(defs.items()):
