def _depth_at(body: str) -> list:
    """Brace depth in front of each character (function body top level = 0)."""
    depths = []
    depth = -1                      # the body's own opening brace lifts us to 0
    for ch in body:
        if ch == "{":
            depths.append(max(depth, 0))
            depth += 1
        elif ch == "}":
            depth -= 1
            depths.append(max(depth, 0))
        else:
            depths.append(max(depth, 0))
    return depths

