def find_package_type(repo_path):
    """Detect what kind of installable package this is."""
    p = Path(repo_path)
    checks = [
        ("setup.py", "pip install ."),
        ("pyproject.toml", "pip install ."),
        ("setup.cfg", "pip install ."),
        ("requirements.txt", "pip install -r requirements.txt"),
        ("package.json", None),  # npm -- not auto-installed
        ("Cargo.toml", None),     # cargo -- not auto-installed
        ("go.mod", None),         # go -- not auto-installed
    ]
    for filename, install_cmd in checks:
        if (p / filename).exists():
            return {"file": filename, "cmd": install_cmd,
                    "language": "python" if install_cmd else filename}
    # even bare .py repos can be imported if they're on sys.path
    py_files = list(p.rglob("*.py"))[:1]
    if py_files:
        return {"file": "*.py", "cmd": "__path__",
                "language": "python-raw"}
    return {"file": None, "cmd": None, "language": "unknown"}

def detect_csrf(response_html: str, response_headers: dict, method: str = 'POST') -> list[dict]:
    """Detect CSRF vulnerabilities in HTTP responses."""
    import re
    findings = []

    # Check forms for CSRF tokens
    forms = re.findall(r'<form[^>]*>(.*?)</form>', response_html, re.DOTALL | re.IGNORECASE)
    token_patterns = [
        r'name=["\'](?:csrf|_csrf|csrfmiddlewaretoken|_token|authenticity_token|__RequestVerificationToken)["\']',
        r'name=["\'][^"]*(?:csrf|xsrf|token)[^"]*["\']',
    ]

    for i, form in enumerate(forms):
        form_action = re.search(r'action=["\']([^"\']*)["\']", form) or 'unknown'
        has_token = any(re.search(p, form, re.IGNORECASE) for p in token_patterns)
        is_state_changing = re.search(r'method=["\'](?:post|put|delete|patch)["\']', form, re.IGNORECASE)

        if is_state_changing and not has_token:
            findings.append({
                'type': 'missing_csrf_token',
                'severity': 'high',
                'form_index': i,
                'detail': f'State-changing form lacks anti-CSRF token',
            })

    # Check cookie attributes
    set_cookie = response_headers.get('set-cookie', '')
    if set_cookie:
        if 'samesite=none' in set_cookie.lower() or 'samesite' not in set_cookie.lower():
            findings.append({
                'type': 'weak_samesite',
                'severity': 'medium',
                'detail': 'Session cookie missing SameSite=Strict or SameSite=Lax',
            })

    # Check for permissive CORS
    acao = response_headers.get('access-control-allow-origin', '')
    acac = response_headers.get('access-control-allow-credentials', '')
    if acao == '*' and acac.lower() == 'true':
        findings.append({
