def audit_linux_hardening(root_path: str = '/') -> dict:
    """Audit Linux system configuration for security hardening compliance."""
    import os

    findings = []

    def check_file(path, checks):
        full = os.path.join(root_path, path.lstrip('/'))
        if not os.path.exists(full):
            findings.append({'check': path, 'status': 'missing', 'severity': 'info'})
            return None
        with open(full) as f:
            return f.read()

    # SSH hardening
    ssh_config = check_file('/etc/ssh/sshd_config', None)
    if ssh_config:
        ssh_checks = [
            ('PermitRootLogin no', 'SSH root login should be disabled', 'critical'),
            ('PasswordAuthentication no', 'SSH password auth should be disabled', 'high'),
            ('X11Forwarding no', 'X11 forwarding should be disabled', 'medium'),
            ('MaxAuthTries', 'MaxAuthTries should be set (recommend 3)', 'medium'),
            ('Protocol 2', 'SSH should use protocol 2 only', 'critical'),
            ('PermitEmptyPasswords no', 'Empty passwords must be denied', 'critical'),
        ]
        for pattern, desc, severity in ssh_checks:
            key = pattern.split()[0]
            if key not in ssh_config or pattern not in ssh_config:
                findings.append({'check': f'sshd: {key}', 'status': 'fail', 'detail': desc, 'severity': severity})
            else:
                findings.append({'check': f'sshd: {key}', 'status': 'pass', 'severity': severity})

    # File permissions
    perm_checks = [
        ('/etc/passwd', 0o644, 'World-writable passwd file'),
        ('/etc/shadow', 0o640, 'Shadow file too permissive'),
        ('/etc/gshadow', 0o640, 'Group shadow too permissive'),
        ('/etc/crontab', 0o600, 'Crontab too permissive'),
    ]
    for path, max_perm, desc in perm_checks:
        full = os.path.join(root_path, path.lstrip('/'))
        if os.path.exists(full):
            actual = os.stat(full).st_mode & 0o777
            if actual > max_perm:
                findings.append({'check': f'perms: {path}', 'status': 'fail', 'actual': oct(actual), 'expected': oct(max_perm), 'severity': 'high'})

    # SUID/SGID binaries
    suid_whitelist = {'/usr/bin/sudo', '/usr/bin/passwd', '/usr/bin/su', '/usr/bin/newgrp', '/usr/bin/chsh', '/usr/bin/chfn'}
    for dirpath, _, filenames in os.walk(os.path.join(root_path, 'usr')):
        for fn in filenames:
            fp = os.path.join(dirpath, fn)
            try:
                st = os.stat(fp)
                if st.st_mode & 0o4000 or st.st_mode & 0o2000:
                    rel = '/' + os.path.relpath(fp, root_path)
                    if rel not in suid_whitelist:
                        findings.append({'check': f'suid: {rel}', 'status': 'warn', 'severity': 'medium', 'detail': 'Unexpected SUID/SGID binary'})
            except (OSError, PermissionError):
                pass

    passed = sum(1 for f in findings if f['status'] == 'pass')
    failed = sum(1 for f in findings if f['status'] == 'fail')

    return {
        'total_checks': len(findings),
        'passed': passed,
        'failed': failed,
        'score': round(passed / max(passed + failed, 1) * 100, 1),
        'findings': findings,
    }

def audit_dockerfile(dockerfile_content: str) -> list[dict]:
    """Analyze a Dockerfile for security misconfigurations."""
    findings = []
    lines = dockerfile_content.strip().split('\n')

    has_user = False
    has_healthcheck = False
    base_image = None

    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        upper = stripped.upper()

        # Check base image
        if upper.startswith('FROM'):
            base_image = stripped.split()[1] if len(stripped.split()) > 1 else ''
            if ':latest' in base_image or ':' not in base_image:
                findings.append({
                    'line': i, 'severity': 'high',
                    'issue': 'Unpinned base image',
                    'detail': f'{base_image} uses :latest or no tag - pin to a specific version',
                    'fix': f'FROM {base_image.split(":")[0]}:22.04  # pin specific version',
                })
            if 'alpine' not in base_image.lower() and 'distroless' not in base_image.lower() and 'scratch' not in base_image.lower():
                findings.append({
                    'line': i, 'severity': 'medium',
                    'issue': 'Large base image',
                    'detail': 'Consider alpine or distroless for smaller attack surface',
                })

        # Running as root
        if upper.startswith('USER'):
            has_user = True
            user = stripped.split()[1] if len(stripped.split()) > 1 else ''
            if user in ('root', '0'):
                findings.append({
                    'line': i, 'severity': 'critical',
                    'issue': 'Container runs as root',
                    'detail': 'Explicitly set to root - use a non-privileged user',
                    'fix': 'USER 1001:1001',
                })

        if upper.startswith('HEALTHCHECK'):
            has_healthcheck = True

        # Dangerous RUN commands
        if upper.startswith('RUN'):
            if 'chmod 777' in stripped:
                findings.append({'line': i, 'severity': 'high', 'issue': 'chmod 777 in RUN', 'detail': 'World-writable permissions - use minimal perms (755 for dirs, 644 for files)'})
            if 'apt-get' in stripped and 'rm -rf /var/lib/apt' not in stripped:
                findings.append({'line': i, 'severity': 'low', 'issue': 'apt cache not cleaned', 'detail': 'Add && rm -rf /var/lib/apt/lists/* to reduce image size'})
            if 'curl' in stripped and 'pipe' in stripped or '| sh' in stripped or '| bash' in stripped:
                findings.append({'line': i, 'severity': 'critical', 'issue': 'Pipe to shell in RUN', 'detail': 'curl | sh is unsafe - download, verify checksum, then execute'})

        # Secrets in ENV/ARG
        if upper.startswith(('ENV', 'ARG')):
            secret_patterns = ['password', 'secret', 'api_key', 'token', 'private_key', 'aws_access']
            for pattern in secret_patterns:
                if pattern in stripped.lower():
                    findings.append({'line': i, 'severity': 'critical', 'issue': 'Secret in Dockerfile', 'detail': f'Possible secret ({pattern}) baked into image layer - use build secrets or runtime env', 'fix': 'RUN --mount=type=secret,id=mytoken ...'})

        # COPY/ADD from broad context
        if upper.startswith('ADD') and ('http' in stripped or 'tar' in stripped):
            findings.append({'line': i, 'severity': 'medium', 'issue': 'ADD with URL/tar', 'detail': 'ADD auto-extracts archives and fetches URLs - prefer COPY + explicit RUN curl'})

        if upper.startswith('COPY . '):
            findings.append({'line': i, 'severity': 'medium', 'issue': 'COPY entire context', 'detail': 'Copies everything including .git, .env, secrets. Use .dockerignore and copy specific paths'})

    if not has_user:
        findings.append({'line': 0, 'severity': 'high', 'issue': 'No USER instruction', 'detail': 'Container will run as root by default', 'fix': 'Add USER 1001:1001 before CMD/ENTRYPOINT'})

    if not has_healthcheck:
        findings.append({'line': 0, 'severity': 'low', 'issue': 'No HEALTHCHECK', 'detail': 'Add HEALTHCHECK for orchestrator-managed restarts'})

    return findings

def find_privesc_vectors(root_path: str = '/') -> dict:
    """Identify privilege escalation vectors on a Linux system."""
    import os
    import stat
    import subprocess

    findings = []

